#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry angle. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Variables J K L : 'rV[R]_2. Variable x : R. Hypotheses HJK : norm (K - J) = x + 7 /\HKL : norm (L - K) = x + 7 /\HJL : norm (L - J) = 4*x - 8 /\Hxpos : x + 7 > 0 /\H4x8pos : 4*x - 8 > 0 /\Hnoncol : ~ collinear J K L. Theorem triangle_KJL_angles : let a := norm (K - J) in let b := norm (L - K) in let c := norm (L - J) in exists alpha beta gamma, alpha + beta + gamma = PI /\alpha = acos ((b^+2 + c^+2 - a^+2)/(2*b*c)) /\beta = acos ((a^+2 + c^+2 - b^+2)/(2*a*c)) /\gamma = acos ((a^+2 + b^+2 - c^+2)/(2*a*b)). Proof. by []. Qed.
